  "inlineSchema": "// prisma/schema.prisma\n// Sisigan Restaurant - Multi-branch POS System\n// Database: MySQL\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─────────────────────────────────────────\n// BRANCH\n// ─────────────────────────────────────────\nmodel Branch {\n  id        Int      @id @default(autoincrement())\n  name      String   @db.VarChar(100)\n  address   String   @db.VarChar(255)\n  city      String   @db.VarChar(100)\n  contactNo String?  @db.VarChar(20)\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  users  User[]\n  orders Order[]\n\n  @@map(\"branches\")\n}\n\n// ─────────────────────────────────────────\n// USER (Staff)\n// ─────────────────────────────────────────\nmodel User {\n  id        Int      @id @default(autoincrement())\n  name      String   @db.VarChar(100)\n  email     String   @unique @db.VarChar(150)\n  password  String   @db.VarChar(255)\n  role      Role     @default(CASHIER)\n  branchId  Int\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  branch Branch  @relation(fields: [branchId], references: [id])\n  orders Order[]\n\n  @@index([branchId])\n  @@map(\"users\")\n}\n\nenum Role {\n  ADMIN\n  MANAGER\n  CASHIER\n}\n\n// ─────────────────────────────────────────\n// MENU\n// ─────────────────────────────────────────\nmodel Category {\n  id        Int      @id @default(autoincrement())\n  name      String   @db.VarChar(100) // e.g. Sisig, Drinks, Add-ons\n  sortOrder Int      @default(0)\n  createdAt DateTime @default(now())\n\n  items MenuItem[]\n\n  @@map(\"categories\")\n}\n\nmodel MenuItem {\n  id          Int      @id @default(autoincrement())\n  name        String   @db.VarChar(150)\n  description String?  @db.Text\n  price       Decimal  @db.Decimal(10, 2)\n  imageUrl    String?  @db.VarChar(500)\n  isAvailable Boolean  @default(true)\n  categoryId  Int\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  category   Category    @relation(fields: [categoryId], references: [id])\n  orderItems OrderItem[]\n\n  @@index([categoryId])\n  @@index([isAvailable])\n  @@map(\"menu_items\")\n}\n\n// ─────────────────────────────────────────\n// ORDER\n// ─────────────────────────────────────────\nmodel Order {\n  id           Int         @id @default(autoincrement())\n  orderNumber  String      @unique @db.VarChar(30) // e.g. BR1-00001\n  status       OrderStatus @default(PENDING)\n  type         OrderType   @default(DINE_IN)\n  tableNumber  String?     @db.VarChar(20)\n  customerName String?     @db.VarChar(100)\n  totalAmount  Decimal     @db.Decimal(10, 2)\n  notes        String?     @db.Text\n  branchId     Int\n  cashierId    Int\n  createdAt    DateTime    @default(now())\n  updatedAt    DateTime    @updatedAt\n\n  branch  Branch      @relation(fields: [branchId], references: [id])\n  cashier User        @relation(fields: [cashierId], references: [id])\n  items   OrderItem[]\n  payment Payment?\n\n  @@index([branchId])\n  @@index([cashierId])\n  @@index([status])\n  @@index([createdAt])\n  @@map(\"orders\")\n}\n\nenum OrderStatus {\n  PENDING // Order received, not yet confirmed\n  PREPARING // Kitchen is preparing\n  READY // Ready for serve/pickup\n  COMPLETED // Paid and done\n  CANCELLED // Void/Cancelled\n}\n\nenum OrderType {\n  DINE_IN\n  TAKEOUT\n  DELIVERY\n}\n\nmodel OrderItem {\n  id         Int     @id @default(autoincrement())\n  orderId    Int\n  menuItemId Int\n  quantity   Int\n  unitPrice  Decimal @db.Decimal(10, 2) // Snapshot of price at time of order\n  subtotal   Decimal @db.Decimal(10, 2)\n  notes      String? @db.VarChar(255) // e.g. \"Extra spicy, no onions\"\n\n  order    Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  menuItem MenuItem @relation(fields: [menuItemId], references: [id])\n\n  @@index([orderId])\n  @@index([menuItemId])\n  @@map(\"order_items\")\n}\n\n// ─────────────────────────────────────────\n// PAYMENT\n// ─────────────────────────────────────────\nmodel Payment {\n  id          Int           @id @default(autoincrement())\n  orderId     Int           @unique\n  method      PaymentMethod\n  amountPaid  Decimal       @db.Decimal(10, 2)\n  change      Decimal       @default(0) @db.Decimal(10, 2)\n  referenceNo String?       @db.VarChar(100) // GCash/Maya/Card ref\n  processedAt DateTime      @default(now())\n\n  order Order @relation(fields: [orderId], references: [id])\n\n  @@map(\"payments\")\n}\n\nenum PaymentMethod {\n  CASH\n  GCASH\n  MAYA\n  CARD\n}\n",
